function Patch-SettingsLanguage {
    param([string]$Content, [string]$FilePath)

    $patterns = @(
        @{ Pattern = 'language:`en`'; Replacement = 'language:(typeof localStorage!=="undefined"&&localStorage.getItem("i18nextLng"))||"ru"' },
        @{ Pattern = 'language:"en"'; Replacement = 'language:(typeof localStorage!=="undefined"&&localStorage.getItem("i18nextLng"))||"ru"' },
