function Mask-Secrets([string]$msg) {
    if (-not $msg) { return "" }

    # Comprehensive secret masking patterns
    $patterns = @(
        # API keys (hex, base64, JWT)
        '[a-fA-F0-9]{48,64}',
        '[A-Za-z0-9+/]{40,}',
        'eyJ[a-zA-Z0-9_-]*\.eyJ[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*',

