        '(?i)(api[_-]?key\s*[:=]\s*["'']?)[^"''\s]+',
        '(?i)(token\s*[:=]\s*["'']?)[^"''\s]+',
        '(?i)(secret\s*[:=]\s*["'']?)[^"''\s]+',
        '(?i)(password\s*[:=]\s*["'']?)[^"''\s]+',

        # URLs with credentials
        '(?i)(https?://)[^@]+@',

        # AWS keys
        'AKIA[0-9A-Z]{16}',

        # Private keys
        '-----BEGIN (RSA |EC |DSA |OPENSSH )?PRIVATE KEY-----'
    )

