function Rotate-Logs {
    param([string]$LogDir, [int]$MaxLogs = 10, [int]$MaxSizeMB = 100)

    if (-not (Test-Path $LogDir)) { return }

    # Remove old logs beyond limit
    $logs = Get-ChildItem -Path $LogDir -File | Sort-Object LastWriteTime -Descending
    if ($logs.Count -gt $MaxLogs) {
        $logs[$MaxLogs..($logs.Count-1)] | Remove-Item -Force
    }

    # Compress large logs
    Get-ChildItem -Path $LogDir -File | Where-Object { $_.Length -gt ($MaxSizeMB * 1MB) } | ForEach-Object {
        $zipPath = "$($_.FullName).gz"
        Compress-Archive -Path $_.FullName -DestinationPath $zipPath -Force
        Remove-Item $_.FullName -Force
    }
}

