```
GitHub API has rate limits (60/hour for unauthenticated, 5000/hour with token).

**Refactored Code:**
```powershell
function Invoke-GitHubAPI {
    param(
        [string]$Uri,
        [int]$MaxRetries = 3
    )

    for ($attempt = 1; $attempt -le $MaxRetries; $attempt++) {
        try {
            $res = Invoke-RestMethod -Uri $Uri -Headers $headers -TimeoutSec 10 -ErrorAction Stop

            # Check rate limit headers
            $remaining = $res.Headers.'X-RateLimit-Remaining'
            if ($remaining -lt 10) {
                Write-Warning "GitHub API rate limit low: $remaining requests remaining"
            }

            return $res
        } catch [System.Net.WebException] {
            if ($_.Exception.Response.StatusCode -eq 403) {
                # Rate limited
                $reset = $_.Exception.Response.Headers.'X-RateLimit-Reset'
                if ($reset) {
                    $wait = [int]$reset - [int](Get-Date -UFormat %s)
                    Write-Warning "Rate limited, waiting $wait seconds"
                    Start-Sleep -Seconds $wait
                    continue
                }
            }
            throw
        }
    }
}

# Usage:
