function Update-Component {
    param(
        [string]$Component,
        [string]$CurrentVersion,
        [string]$LatestVersion,
        [scriptblock]$UpdateScript
    )

    if ($CurrentVersion -eq $LatestVersion) {
        return $true
    }

    # Create backup before update
    $backupPath = Join-Path $Global:BackupDir "$Component-$CurrentVersion"
    New-Item -ItemType Directory -Path $backupPath -Force | Out-Null

    try {
        # Execute update
        & $UpdateScript

        # Verify update succeeded
        $newVersion = Get-ComponentVersion -Component $Component
        if ($newVersion -eq $LatestVersion) {
            Write-Host "$Component updated successfully" -ForegroundColor Green
            return $true
        } else {
            throw "Update verification failed"
        }
    } catch {
        # Rollback on failure
        Write-Error "Update failed, rolling back..."
        Restore-Component -Component $Component -BackupPath $backupPath
        throw
    }
}
