function Verify-BackupIntegrity {
    param([string]$BackupFolder)

    $manifestPath = Join-Path $BackupFolder "BACKUP_MANIFEST.json"
    if (-not (Test-Path $manifestPath)) {
        return $false
    }

    $manifest = Get-Content $manifestPath -Raw | ConvertFrom-Json

    # Verify file count matches
    $actualCount = (Get-ChildItem -Path $BackupFolder -Recurse -File).Count
    if ($actualCount -ne $manifest.files_count) {
        Write-Error "File count mismatch: expected $($manifest.files_count), got $actualCount"
        return $false
    }

    # Verify total size matches
    $actualSize = (Get-ChildItem -Path $BackupFolder -Recurse -File | Measure-Object -Property Length -Sum).Sum
    if ($actualSize -ne $manifest.total_bytes) {
        Write-Error "Size mismatch: expected $($manifest.total_bytes), got $actualSize"
        return $false
    }

    return $true
}

# Usage:
if (-not (Verify-BackupIntegrity -BackupFolder $targetBackupFolder)) {
    Write-Error "Backup integrity verification failed"
    exit 1
}
