**Refactored Code:**
```powershell
function Restore-With-Rollback {
    param(
        [string]$Source,
        [string]$Destination,
        [string]$ComponentName
    )

    # Create rollback point
    $rollbackPath = Join-Path $Global:BackupDir "restore-rollback-$ComponentName"
    if (Test-Path $Destination) {
        Fast-CopyDir $Destination $rollbackPath -Mirror
    }

    try {
        Fast-CopyDir $Source $Destination
        return $true
    } catch {
        # Rollback on failure
        Write-Error "Restore failed for $ComponentName, rolling back..."
        Fast-CopyDir $rollbackPath $Destination -Mirror
        throw
    } finally {
        if (Test-Path $rollbackPath) {
            Remove-Item $rollbackPath -Recurse -Force
        }
    }
}

# Usage:
Restore-With-Rollback -Source $srcConfig -Destination (Join-Path $ProjectRoot "Config") -ComponentName "Config"
